for (int i = 1; i <= n; i++) {
    int j = 1;
    while (j < n) {
        work();
        j *= 2;          // 1,2,4,... < n，共 O(log n) 次
    }
}
// 外层 n 次，内层 O(log n)，时间 O(n log n)，额外空间 O(1)。

int f(int n) {
    if (n <= 1) return 1;
    return f(n/2) + f(n/2) + n;   // T(n)=2T(n/2)+n
}
