CREATE TABLE users (
  id BIGINT PRIMARY KEY,
  email VARCHAR(255) UNIQUE,
  name VARCHAR(64),
  created_at DATETIME
);

-- 回表：二级索引 email -> 主键 id -> 聚簇索引取 name
SELECT name FROM users WHERE email = 'a@example.com';

-- 覆盖索引：二级索引直接包含 name
ALTER TABLE users ADD INDEX idx_email_name (email, name);

CREATE INDEX idx_abc ON t (a, b, c);

-- a 等值、b 范围，c 作为索引条件下推过滤
